// mockIcon writes the icon name as an inline svg with the class "i" (extra adds
// classes). Names come from templates and code, never from users.
func mockIcon(name string, extra ...string) template.HTML {
	body, ok := mockIcons[name]
	if !ok {
		return ""
	}
	cls := "i"
	if len(extra) > 0 {
		cls += " " + strings.Join(extra, " ")
	}
	return template.HTML(`<svg class="` + cls + `" viewBox="0 0 16 16" aria-hidden="true">` + body + `</svg>`)
}

// brandMark writes the logo of a harness (claude, codex) as an inline svg.
func brandMark(name string) template.HTML {
	p, ok := brandPaths[name]
	if !ok {
		return ""
	}
	return template.HTML(`<svg class="i brand" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" stroke="none" d="` + p + `"/></svg>`)
}
